glsl4.vert:
precision highp float;
layout(set = 0, binding = 1) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
layout(set = 2, binding = 0) uniform CCLocal {
  highp mat4 cc_matWorld;
  highp mat4 cc_matWorldIT;
  highp vec4 cc_lightingMapUVParam;
  highp vec4 cc_localShadowBias;
};
layout(set = 1, binding = 0) uniform Constants {
  vec4 wave;
  vec4 impact;
};
layout(location = 0) in vec3 a_position;
out highp float focusing;
// Three deterministic gravity waves, shared by displacement and caustics.
// Return height and analytic x/z derivatives; amplitude is in world units.
vec3 waveField(vec2 p) {
    vec2 d0 = normalize(vec2(1.0, 0.35));
    vec2 d1 = normalize(vec2(-0.4, 1.0));
    vec2 d2 = normalize(vec2(0.8, -0.6));
    float a = wave.x;
    float s0 = dot(p, d0) * 1.7 + wave.y * 1.25 + wave.z;
    float s1 = dot(p, d1) * 2.8 - wave.y * 1.65 + wave.z * 0.73;
    float s2 = dot(p, d2) * 5.1 + wave.y * 2.15 + wave.z * 1.37;
    float h = a * (sin(s0) + 0.48 * sin(s1) + 0.18 * sin(s2));
    vec2 g = a * (1.7 * cos(s0) * d0 + 1.344 * cos(s1) * d1 + 0.918 * cos(s2) * d2);
    vec2 delta = p - impact.xy;
    float radius = max(length(delta), 0.0001);
    float age = max(wave.y - impact.z, 0.0);
    float ring = radius - 0.15 - age * 1.4;
    float envelope = impact.w * 0.085 * exp(-ring * ring * 35.0 - age * 1.6);
    float phase = radius * 22.0 - age * 8.0;
    h += envelope * sin(phase);
    g += delta / radius * envelope * (22.0 * cos(phase) - 70.0 * ring * sin(phase));
    vec2 cell = floor(p / 1.6);
    vec2 rainDelta = p - (cell + 0.5) * 1.6;
    float rainR = max(length(rainDelta), 0.0001);
    float rainAge = fract(wave.y * 0.85 + sin(dot(cell, vec2(12.73, 45.91))) * 437.1);
    float rainRing = rainR - rainAge * 0.85;
    float rainEnvelope = wave.w * 0.026 * exp(-rainRing * rainRing * 55.0 - rainAge * 1.4);
    h += rainEnvelope * sin(rainR * 26.0 - rainAge * 9.0);
    g += rainDelta / rainR * rainEnvelope * (26.0 * cos(rainR * 26.0 - rainAge * 9.0) - 110.0 * rainRing * sin(rainR * 26.0 - rainAge * 9.0));
    return vec3(h, g);
}

vec2 rayLanding(vec2 p) {
    vec3 f = waveField(p);
    vec3 normal = normalize(vec3(-f.y, 1.0, -f.z));
    vec3 ray = refract(normalize(vec3(0.4, -0.9, -0.3)), normal, 1.0 / 1.333);
    return p + ray.xz * ((2.0 + f.x) / max(-ray.y, 0.1));
}
void main() {
    vec2 p = a_position.xz;
    float e = 0.015;
    vec2 landing = rayLanding(p);
    vec2 dx = (rayLanding(p + vec2(e, 0.0)) - rayLanding(p - vec2(e, 0.0))) / (2.0 * e);
    vec2 dz = (rayLanding(p + vec2(0.0, e)) - rayLanding(p - vec2(0.0, e))) / (2.0 * e);
    float determinant = abs(dx.x * dz.y - dx.y * dz.x);
    focusing = clamp(1.0 / max(determinant, 0.12), 0.0, 4.0);
    gl_Position = cc_matViewProj * vec4(landing.x, -2.0, landing.y, 1.0);
}

glsl4.frag:
precision highp float;
layout(set = 0, binding = 0) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_debug_view_mode;
};
layout(set = 1, binding = 0) uniform Constants {
  vec4 wave;
  vec4 impact;
};
in highp float focusing;
layout(location = 0) out vec4 cc_FragColor;
void main() {
    float focus = max(focusing - 0.78, 0.0) * 0.32;
    cc_FragColor = vec4(vec3(0.70, 0.90, 1.0) * focus, 1.0);
}

